package com.example.case1.analytics.sink; import com.example.case1.analytics.model.TransactionEvent; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Component;
@Component @ConditionalOnProperty(name="app.sink",havingValue="snowflake") public class SnowflakeAnalyticsSink implements AnalyticsSink { private final JdbcTemplate jdbc; public SnowflakeAnalyticsSink(JdbcTemplate jdbc){this.jdbc=jdbc;} public void write(TransactionEvent e){jdbc.update("merge into TRANSACTION_ANALYTICS t using (select ? EVENT_ID, ? LEDGER_ID, ? TRANSACTION_ID, ? AMOUNT, ? CURRENCY, ? SETTLEMENT_DATE, ? STATUS, ? OCCURRED_AT) s on t.EVENT_ID=s.EVENT_ID when not matched then insert (EVENT_ID,LEDGER_ID,TRANSACTION_ID,AMOUNT,CURRENCY,SETTLEMENT_DATE,STATUS,OCCURRED_AT) values(s.EVENT_ID,s.LEDGER_ID,s.TRANSACTION_ID,s.AMOUNT,s.CURRENCY,s.SETTLEMENT_DATE,s.STATUS,s.OCCURRED_AT)",e.eventId().toString(),e.ledgerId().toString(),e.transactionId(),e.amount(),e.currency(),e.settlementDate(),e.status(),e.occurredAt());} }
